// AVL Tree — O(log n) insert, search, delete
class AVLNode {
  constructor(key) {
    this.key    = key;
    this.left   = null;
    this.right  = null;
    this.height = 1;
  }
}

class AVLTree {
  #root = null;

  #h(n)            { return n ? n.height : 0; }
  #bf(n)           { return n ? this.#h(n.left) - this.#h(n.right) : 0; }
  #updateH(n)      { n.height = 1 + Math.max(this.#h(n.left), this.#h(n.right)); }

  #rotateRight(y) {
    const x  = y.left;
    const T2 = x.right;
    x.right  = y;
    y.left   = T2;
    this.#updateH(y);
    this.#updateH(x);
    return x; // x is new subtree root
  }

  #rotateLeft(x) {
    const y  = x.right;
    const T2 = y.left;
    y.left   = x;
    x.right  = T2;
    this.#updateH(x);
    this.#updateH(y);
    return y;
  }

  #balance(node) {
    this.#updateH(node);
    const bf = this.#bf(node);
    if (bf > 1)  { // left-heavy
      if (this.#bf(node.left) < 0)           // LR case
        node.left = this.#rotateLeft(node.left);
      return this.#rotateRight(node);         // LL case
    }
    if (bf < -1) { // right-heavy
      if (this.#bf(node.right) > 0)           // RL case
        node.right = this.#rotateRight(node.right);
      return this.#rotateLeft(node);          // RR case
    }
    return node; // already balanced
  }

  #insert(node, key) {
    if (!node) return new AVLNode(key);
    if      (key < node.key) node.left  = this.#insert(node.left,  key);
    else if (key > node.key) node.right = this.#insert(node.right, key);
    else                     return node; // duplicate
    return this.#balance(node);
  }

  insert(key)  { this.#root = this.#insert(this.#root, key); }
  height()     { return this.#h(this.#root); }

  search(key) {
    let node = this.#root;
    while (node) {
      if      (key === node.key) return true;
      else if (key  <  node.key) node = node.left;
      else                       node = node.right;
    }
    return false;
  }
}

const avl = new AVLTree();
[10, 20, 30, 40, 50, 25].forEach(k => avl.insert(k));
console.log('height:', avl.height());    // 3 (not 6 as in degenerate BST)
console.log(avl.search(25));             // true
console.log(avl.search(99));             // false

// Comparison: AVL vs Red-Black vs B-Tree
//
// AVL Tree
// - Balance factor: |left_height - right_height| <= 1
// - Max height: 1.44 * log2(n)   ← stricter, shorter
// - Rotations per insert: up to 2  (constant)
// - Rotations per delete: up to O(log n)
// - Best for: read-heavy workloads, in-memory sorted maps

// Red-Black Tree
// - Colour invariant: equal black-height on every root-to-null path, no 2 adjacent reds
// - Max height: 2 * log2(n+1)    ← relaxed, slightly taller
// - Rotations per insert: at most 2
// - Rotations per delete: at most 3
// - Best for: write-heavy workloads (Java TreeMap, C++ std::map, Linux CFS)

// B-Tree (order M)
// - Nodes hold M-1 keys and up to M children
// - All leaves at same depth (perfect height balance)
// - Node fits one disk page → minimises I/O
// - Height: log_M(n) ← M=200 means 3-4 levels for millions of records
// - B+ Tree: all records in leaves, leaves linked → fast range scans
// - Best for: database indexes, file systems (NTFS, ext4, HFS+)

// Complexity summary
const ops = [
//  structure    search       insert       delete
  ['BST (avg)',  'O(log n)', 'O(log n)',  'O(log n)'],
  ['BST (worst)','O(n)',     'O(n)',      'O(n)'    ],
  ['AVL',        'O(log n)', 'O(log n)', 'O(log n)'],
  ['Red-Black',  'O(log n)', 'O(log n)', 'O(log n)'],
  ['B-Tree',     'O(log n)', 'O(log n)', 'O(log n)']
];
ops.forEach(([s,r,i,d]) => console.log(`${s}: search ${r} insert ${i} delete ${d}`));
